reg debug_print;
initial begin
  if (!$value$plusargs("DEBUG=%d", debug_print)) begin
    debug_print = 0;
  end
end

always @(posedge clock) begin
  if (debug_print) begin
    if (core.rob_io_commit_valids_0 & ~core.reset) begin
      $fwrite(32'h80000001, "%d 0x%x ", core._T_617, core._T_622);
    end
    if (core._GEN_92 & ~core.reset) begin
      $fwrite(32'h80000001,"(0x%x) DASM(%x)\n", core.rob_io_commit_uops_0_debug_inst[15:0], core.rob_io_commit_uops_0_debug_inst[15:0]); // @[core.scala 1258:17]
    end
    if (core._GEN_94 & ~core.reset) begin
